<div class="container">
    <div class="panel">
        <h1>Kitchen Rescue</h1>
        <div class="subtitle">Turn expiring scraps into an immediate use-today culinary plan.</div>

        <div class="form-group">
            <label for="ingredientsInput">What needs rescuing?</label>
            <textarea id="ingredientsInput" placeholder="2 eggs (expires tomorrow)&#10;Half a pack of bacon&#10;Wilted spinach&#10;1 can black beans&#10;Leftover heavy cream (open 4 days)&#10;Sour cream"></textarea>
            <div class="hint">List items line by line. Mention expiry or condition if you want it prioritized.</div>
        </div>

        <button onclick="generateRescuePlan()">Generate Rescue Plan</button>
    </div>

    <div class="panel" id="outputPanel">
        <div class="placeholder-text">Input your ingredients and hit generate to construct your culinary battle plan.</div>
    </div>
</div>

<script>
function generateRescuePlan() {
    const input = document.getElementById('ingredientsInput').value.trim();
    const outputPanel = document.getElementById('outputPanel');

    if (!input) {
        outputPanel.innerHTML = '<div class="placeholder-text">Please enter some ingredients first.</div>';
        return;
    }

    const lines = input.split('\n').map(line => line.trim()).filter(line => line.length > 0);

    let criticalItems = [];
    let warningItems = [];
    let standardItems = [];

    // Simple heuristic parser for expiration/urgency
    lines.forEach(item => {
        const lower = item.toLowerCase();
        if (lower.includes('tomorrow') || lower.includes('today') || lower.includes('expire') || lower.includes('wilt') || lower.includes('open') || lower.includes('bad') || lower.includes('critical')) {
            criticalItems.push(item);
        } else if (lower.includes('days') || lower.includes('week') || lower.includes('old') || lower.includes('soft')) {
            warningItems.push(item);
        } else {
            standardItems.push(item);
        }
    });

    // Fallbacks if categories are empty to ensure all items are mapped somewhere
    if (criticalItems.length === 0 && warningItems.length === 0 && standardItems.length > 0) {
        criticalItems = [standardItems.shift()];
        if (standardItems.length > 0) warningItems = [standardItems.shift()];
    }

    let html = `<h2>Culinary Rescue Plan</h2><div class="subtitle">Generated tactical strategy based on item priorities.</div>`;

    // Strategy 1: Immediate Execution (Critical items)
    if (criticalItems.length > 0) {
        const combinedCritical = criticalItems.map(i => `<span>${i}</span>`).join('');
        html += `
        <div class="timeline-section">
            <div class="timeline-header">
                <span class="badge critical">Priority 1</span> Use Within 12 Hours
            </div>
            <div class="recipe-card critical">
                <div class="recipe-title">The "Clear the Fridge" Main Event</div>
                <div class="used-ingredients"><strong>Rescuing:</strong> ${combinedCritical}</div>
                <ul class="instructions">
                    <li><strong>The Base:</strong> If you have grains (rice, pasta) or eggs, make a scramble, fried rice, or hash. If liquid-heavy, pivot to a soup or sauce base.</li>
                    <li><strong>The Prep:</strong> Chop all priority ingredients uniformly to ensure even cooking. Sauté hard ingredients first (bacon, onions), then add soft items, and throw in greens or pre-cooked proteins at the very end.</li>
                    <li><strong>The Binding Force:</strong> Use those open dairy items, cheeses, or a splash of stock to bind the ingredients together into a cohesive skillet meal or bake.</li>
                </ul>
            </div>
        </div>`;
    }

    // Strategy 2: Next Meal Setup (Warning items)
    if (warningItems.length > 0 || standardItems.length > 0) {
        const remaining = [...warningItems, ...standardItems];
        const combinedWarning = remaining.map(i => `<span>${i}</span>`).join('');
        html += `
        <div class="timeline-section">
            <div class="timeline-header">
                <span class="badge warning">Priority 2</span> The Next Meal / Prep Ahead
            </div>
            <div class="recipe-card warning">
                <div class="recipe-title">The Secondary Defensive Strategy</div>
                <div class="used-ingredients"><strong>Utilizing:</strong> ${combinedWarning}</div>
                <ul class="instructions">
                    <li><strong>Roast or Boil:</strong> Toss remaining vegetables in olive oil, salt, and pepper, then roast at 400°F (200°C) to extend their lifespan by 3-4 days.</li>
                    <li><strong>The Sauce/Marinade Hack:</strong> Blend herbs, fading greens, and leftover oils or acids (lemon, vinegar) into a pesto or marinade for future proteins.</li>
                    <li><strong>Canned Goods Integration:</strong> Open up the identified cans to stretch the meal. Simmer beans or proteins into a quick chili, stew, or cold bean salad.</li>
                </ul>
            </div>
        </div>`;
    }

    // Strategy 3: Preservation (Long-term save)
    html += `
    <div class="timeline-section">
        <div class="timeline-header">
            <span class="badge flex">Preservation</span> The Deep Freeze Escape Hatch
        </div>
        <div class="recipe-card flex">
            <div class="recipe-title">When You Can't Eat It All Today</div>
            <ul class="instructions">
                <li><strong>Ice Cube Tray Hack:</strong> Pour excess heavy cream, sauces, or blended herb pastes into ice cube trays. Freeze, then transfer to a zip bag.</li>
                <li><strong>The Scrap Bag:</strong> Toss raw vegetable trim, stems, and leftover onion pieces into a gallon bag in the freezer. When full, boil for homemade vegetable stock.</li>
                <li><strong>Pre-emptive Freezing:</strong> Most proteins, cheeses (shredded), and breads can go straight into the freezer right now to halt the expiration clock completely.</li>
            </ul>
        </div>
    </div>`;

    outputPanel.innerHTML = html;
}
</script>

</body>
</html>
"""

file_path = "kitchen_rescue_plan.html"
with open(file_path, "w") as f:
    f.write(html_content)
print(f"File created successfully: {file_path}")



