        const portions = document.getElementById('itemPortions').value.trim() || '1 unit';
        const constraintsRaw = document.getElementById('itemConstraints').value;

        const constraints = constraintsRaw ? constraintsRaw.split(',').map(t => t.trim()).filter(t => t.length > 0) : [];

        const newItem = {
            id: Date.now(),
            name,
            location,
            expiry,
            portions,
