            const tagsHtml = item.constraints.map(t => `<span class="tag">${t}</span>`).join('');

            tr.innerHTML = `
                <strong>${item.name}</strong>
                <td>${item.location}</td>
                <td style="color: ${item.expiry <= 2 ? 'var(--accent-urgent)' : 'inherit'}; font-weight: ${item.expiry <= 2 ? 'bold' : 'normal'};">${item.expiry}d</td>
                <td>${item.portions}</td>
                <td>${tagsHtml}</td>
                <td><button class="delete-btn" onclick="deleteItem(${item.id})">&times;</button></td>
            `;
            tbody.appendChild(tr);
        });
