    function generateRescuePlan() {
        const outputPanel = document.getElementById('outputPanel');

        if (inventory.length === 0) {
            outputPanel.innerHTML = '<div class="placeholder-text">Add ingredients to see your active rescue strategy auto-update here.</div>';
            return;
        }

        // Group into Tiers based on strict expiration criteria
        const tier1 = inventory.filter(i => i.expiry <= 2);
        const tier2 = inventory.filter(i => i.expiry > 2 && i.expiry <= 5);
        const tier3 = inventory.filter(i => i.expiry > 5);

        let html = `<h2>Active Rescue Strategy</h2><div class="subtitle">Live culinary configuration mapping current tracking items.</div>`;

        // Tier 1: Immediate Execution (0-2 Days Remaining)
        if (tier1.length > 0) {
            const combinedTier1 = tier1.map(i => {
                const tagStr = i.constraints.length ? ` (${i.constraints.join(', ')})` : '';
                return `<span>${i.portions} ${i.name}${tagStr}</span>`;
