            updateUI();
        }
    });

    function saveToStorage() {
        localStorage.setItem('kitchenRescueInventory', JSON.stringify(inventory));
    }

    function addIngredient(e) {
        e.preventDefault();

        const name = document.getElementById('itemName').value.trim();
        const location = document.getElementById('itemLocation').value;
        const expiry = parseInt(document.getElementById('itemExpiry').value);
        const portions = document.getElementById('itemPortions').value.trim() || '1 unit';
        const constraintsRaw = document.getElementById('itemConstraints').value;

        const constraints = constraintsRaw ? constraintsRaw.split(',').map(t => t.trim().toLowerCase()).filter(t => t.length > 0) : [];

        const newItem = {
            id: Date.now(),
            name,
            location,
            expiry,
            portions,
            constraints
        };

        inventory.push(newItem);
        saveToStorage();
        updateUI();

        document.getElementById('itemName').value = '';
        document.getElementById('itemExpiry').value = '';
        document.getElementById('itemPortions').value = '';
        document.getElementById('itemConstraints').value = '';
        document.getElementById('itemName').focus();
    }

    function deleteItem(id) {
        inventory = inventory.filter(item => item.id !== id);
        saveToStorage();
        updateUI();
    }

    function clearInventory() {
        if(confirm("Clear entire active local storage inventory?")) {
            inventory = [];
            saveToStorage();
            updateUI();
        }
