                </ol>
            </div>`;

            if (expiringItems.length > 1) {
                const subBatch1 = expiringItems.slice(0, Math.ceil(expiringItems.length / 2));
                const subBatch2 = expiringItems.slice(Math.ceil(expiringItems.length / 2));
