    });

    function saveToStorage() {
        localStorage.setItem('kitchenRescueInventory', JSON.stringify(inventory));
    }

    function loadDemoData() {
        inventory = [
            { id: 1, name: "Baby Spinach", location: "Fridge", expiry: 1, portions: "2 bags", constraints: ["vegetarian", "dairy-free", "quick"] },
            { id: 2, name: "Firm Tofu", location: "Fridge", expiry: 2, portions: "1 block", constraints: ["vegetarian", "dairy-free", "no oven"] },
            { id: 3, name: "Almond Milk", location: "Fridge", expiry: 5, portions: "0.5 gal", constraints: ["vegetarian", "dairy-free"] },
            { id: 4, name: "Rolled Oats", location: "Pantry", expiry: 20, portions: "1 tub", constraints: ["vegetarian", "dairy-free", "quick"] }
        ];
        saveToStorage();
        updateUI();
    }

    function addIngredient(e) {
        e.preventDefault();

        const name = document.getElementById('itemName').value.trim();
        const location = document.getElementById('itemLocation').value;
        const expiry = parseInt(document.getElementById('itemExpiry').value);
        const portions = document.getElementById('itemPortions').value.trim() || '1 unit';
        const constraintsRaw = document.getElementById('itemConstraints').value;

        const constraints = constraintsRaw ? constraintsRaw.split(',').map(t => t.trim().toLowerCase()).filter(t => t.length > 0) : [];

        const newItem = {
            id: Date.now(),
            name,
            location,
            expiry,
            portions,
            constraints
        };

        inventory.push(newItem);
        saveToStorage();
        updateUI();

        document.getElementById('itemName').value = '';
        document.getElementById('itemExpiry').value = '';
        document.getElementById('itemPortions').value = '';
        document.getElementById('itemConstraints').value = '';
    }

    function deleteItem(id) {
        inventory = inventory.filter(item => item.id !== id);
        saveToStorage();
        updateUI();
    }

    function clearInventory() {
        if(confirm("Wipe active tracking window?")) {
            inventory = [];
            saveToStorage();
            updateUI();
        }
    }

    function updateUI() {
        renderTable();
        generateRescuePlan();
    }

    function renderTable() {
        const tbody = document.getElementById('inventoryTableBody');
        tbody.innerHTML = '';

        if (inventory.length === 0) {
            tbody.innerHTML = `<tr><td colspan="6" style="text-align:center; color: #7f8c8d; font-style: italic; padding:15px;">No items tracked</td></tr>`;
            return;
        }

        const sortedDisplay = [...inventory].sort((a, b) => a.expiry - b.expiry);

        sortedDisplay.forEach(item => {
            const tr = document.createElement('tr');
            const tagsHtml = item.constraints.map(t => `<span class="tag">${t}</span>`).join('');

            tr.innerHTML = `
                <td><strong>${item.name}</strong></td>
                <td>${item.location}</td>
                <td style="color: ${item.expiry <= 2 ? 'var(--accent-urgent)' : 'inherit'}; font-weight: ${item.expiry <= 2 ? 'bold' : 'normal'};">${item.expiry}d</td>
                <td>${item.portions}</td>
                <td><div style="max-width:80px; overflow:hidden; text-overflow:ellipsis;">${tagsHtml}</div></td>
                <td><button class="delete-btn" onclick="deleteItem(${item.id})">&times;</button></td>
            `;
            tbody.appendChild(tr);
        });
    }

    function generateRescuePlan() {
        const outputPanel = document.getElementById('outputPanel');
        const utils = document.getElementById('outputUtilities');

        if (inventory.length === 0) {
            outputPanel.innerHTML = '<div class="placeholder-text">Load the demo data or enter items manually to build structural strategy lines.</div>';
            utils.style.display = 'none';
            return;
        }
        utils.style.display = 'flex';

        const expiringItems = inventory.filter(i => i.expiry <= 2);
        let html = `<h2>Active Rescue Strategy</h2>`;

        if (expiringItems.length > 0) {
            html += `
            <div class="section-block">
                <div class="section-title">
                    <span class="badge now">Use Now</span> Immediate Combinations
                </div>`;

            const allExpiringTags = expiringItems.flatMap(i => i.constraints);
            const isVegetarian = allExpiringTags.includes('vegetarian');
            const isDairyFree = allExpiringTags.includes('dairy-free');
            const isNoOven = allExpiringTags.includes('no oven') || allExpiringTags.includes('no-oven');
            const isQuick = allExpiringTags.includes('quick');

            let combo1Title = isQuick ? "10-Min Flash Scramble/Stir-Fry" : "Unified Skillet Toss";
            if (isNoOven) combo1Title += " (Stovetop)";

            let combo1Steps = [
                `Heat cooking oil in a pan over high heat. ${isNoOven ? 'Keep oven off completely.' : ''}`,
                `Throw in high-alert elements: ${expiringItems.map(i => i.name).join(', ')}.`,
                isDairyFree ? "Season aggressively with chili flakes, salt, or sauce; omit butter/dairy blocks entirely." : "Stir in cheese shreds or sour cream ends to link ingredients."
            ];

            html += `
            <div class="combo-card">
                <div class="combo-header">
                    <div class="combo-name">${combo1Title}</div>
                    <div class="match-tags">
                        ${isVegetarian ? '<span class="match-tag">Veg</span>' : ''}
                        ${isDairyFree ? '<span class="match-tag">DF</span>' : ''}
                        ${isQuick ? '<span class="match-tag">Quick</span>' : ''}
                    </div>
                </div>
                <div class="used-ingredients"><strong>Processing:</strong> ${expiringItems.map(i => i.name).join(', ')}</div>
                <ol class="combo-steps">
                    ${combo1Steps.map(step => `<li>${step}</li>`).join('')}
                </ol>
            </div>`;

            if (expiringItems.length > 1) {
                const subBatch1 = expiringItems.slice(0, Math.ceil(expiringItems.length / 2));
                const subBatch2 = expiringItems.slice(Math.ceil(expiringItems.length / 2));
                let combo2Title = isVegetarian ? "Plant-Forward Cleanse Bowl" : "Layered Protein Base";

                html += `
                <div class="combo-card">
                    <div class="combo-header">
                        <div class="combo-name">${combo2Title}</div>
                    </div>
                    <div class="used-ingredients"><strong>Base:</strong> ${subBatch1.map(i => i.name).join(', ')} | <strong>Top:</strong> ${subBatch2.map(i => i.name).join(', ')}</div>
                    <ol class="combo-steps">
                        <li>Sauté and dress ${subBatch1.map(i => i.name).join(', ')} separately to establish flavor core.</li>
                        <li>Add a swift heat-flash to ${subBatch2.map(i => i.name).join(', ')} and layer on top.</li>
                    </ol>
                </div>`;
            }
            html += `</div>`;
        }

        const tier1 = inventory.filter(i => i.expiry <= 2);
        const tier2 = inventory.filter(i => i.expiry > 2 && i.expiry <= 5);
        const tier3 = inventory.filter(i => i.expiry > 5);

        html += `<div class="section-block">
            <div class="section-title"><span class="badge tier">Tracking</span> Pipeline Buckets</div>`;

        if (tier1.length > 0) {
            html += `
            <div class="recipe-card" style="border-left-color: var(--accent-urgent);">
                <div class="recipe-title">Tier 1: Critical (0-2 Days)</div>
                <div>Exhaust immediately using the combo layouts mapped above.</div>
            </div>`;
        }

        if (tier2.length > 0) {
            html += `
            <div class="recipe-card" style="border-left-color: var(--accent-warning);">
                <div class="recipe-title">Tier 2: Intermediate (3-5 Days)</div>
                <div><strong>Items:</strong> ${tier2.map(i => i.name).join(', ')}</div>
            </div>`;
        }

        if (tier3.length > 0) {
            html += `
            <div class="recipe-card" style="border-left-color: var(--accent-safe);">
                <div class="recipe-title">Tier 3: Stable (6+ Days)</div>
                <div><strong>Items:</strong> ${tier3.map(i => i.name).join(', ')}</div>
            </div>`;
        }

        html += `</div>`;
        outputPanel.innerHTML = html;
    }

    function copyPlanToClipboard() {
        const expiringItems = inventory.filter(i => i.expiry <= 2);
        if (expiringItems.length === 0) {
            alert("No critical items current to copy.");
            return;
        }
        let txt = `RESCUE PLAN\\n\\nURGENT:\\n`;
        expiringItems.forEach(i => { txt += `- ${i.portions} ${i.name}\\n`; });
        txt += `\\nCOMBOS:\\n1. Skillet Toss (${expiringItems.map(i => i.name).join(', ')})`;

        navigator.clipboard.writeText(txt).then(() => {
            alert("Copied directly to clipboard!");
        });
    }

    function exportInventory() {
        if (inventory.length === 0) return alert("Nothing to export.");
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(inventory, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", "kitchen_inventory.json");
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
    }

    function importInventory(event) {
        const file = event.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = function(e) {
            try {
                const parsed = JSON.parse(e.target.result);
                if (Array.isArray(parsed)) {
                    inventory = parsed;
                    saveToStorage();
                    updateUI();
                }
            } catch (err) { alert("Invalid format."); }
        };
        reader.readAsText(file);
        event.target.value = '';
    }
</script>

</body>
</html>
"""

file_path_v5 = "kitchen_rescue_mobile.html"
with open(file_path_v5, "w") as f:
    f.write(html_content_v5)
